#include <stdio.h>
#include <stdlib.h>

#define INF 100000000
#define NEG_INF (-100000000)

typedef struct {
    int u, v, rev;
} Edge;

static Edge *edges;
static int *degree_arr, *start, *tree_size, *offset;
static int *min_tree, *lazy_tree, *max_tree, *dp, *queue_arr;
static int qtail;

static int cmp_edge(const void *pa, const void *pb) {
    const Edge *a = (const Edge *)pa;
    const Edge *b = (const Edge *)pb;
    if (a->u != b->u) return (a->u > b->u) - (a->u < b->u);
    return (a->v > b->v) - (a->v < b->v);
}

static int find_edge(int u, int v, int E) {
    int lo = 0, hi = E;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (edges[mid].u < u || (edges[mid].u == u && edges[mid].v < v))
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

static void range_add(int vertex, int node, int left, int right,
                      int ql, int qr, int value) {
    int base = offset[vertex];
    if (ql <= left && right <= qr) {
        min_tree[base + node] += value;
        lazy_tree[base + node] += value;
        return;
    }

    int mid = (left + right) / 2;
    int lc = node * 2, rc = lc + 1;

    if (lazy_tree[base + node] != 0) {
        int val = lazy_tree[base + node];
        min_tree[base + lc] += val;
        min_tree[base + rc] += val;
        lazy_tree[base + lc] += val;
        lazy_tree[base + rc] += val;
        lazy_tree[base + node] = 0;
    }

    if (ql < mid)
        range_add(vertex, lc, left, mid, ql, qr, value);
    if (qr > mid)
        range_add(vertex, rc, mid, right, ql, qr, value);

    int a = min_tree[base + lc], b = min_tree[base + rc];
    min_tree[base + node] = a < b ? a : b;
}

static void max_update(int vertex, int pos, int value) {
    int base = offset[vertex];
    int s = tree_size[vertex];
    int node = s + pos;
    max_tree[base + node] = value;
    for (node >>= 1; node; node >>= 1) {
        int a = max_tree[base + node * 2];
        int b = max_tree[base + node * 2 + 1];
        max_tree[base + node] = a > b ? a : b;
    }
}

static int max_query(int vertex, int left, int right) {
    int base = offset[vertex];
    int s = tree_size[vertex];
    int l = left + s, r = right + s;
    int answer = NEG_INF;

    while (l < r) {
        if (l & 1) {
            if (max_tree[base + l] > answer) answer = max_tree[base + l];
            ++l;
        }
        if (r & 1) {
            --r;
            if (max_tree[base + r] > answer) answer = max_tree[base + r];
        }
        l >>= 1;
        r >>= 1;
    }
    return answer;
}

static void extract_zeros(int vertex, int node, int left, int right) {
    int base = offset[vertex];
    if (min_tree[base + node] != 0) return;

    if (right - left == 1) {
        if (left < degree_arr[vertex]) {
            int state = edges[start[vertex] + left].rev;
            dp[state] = 1 + max_query(vertex, left + 1, degree_arr[vertex]);
            queue_arr[qtail++] = state;
        }
        min_tree[base + node] = INF;
        lazy_tree[base + node] = 0;
        return;
