    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int E = 2 * M;
    edges = (Edge *)malloc((size_t)(E ? E : 1) * sizeof(Edge));
    degree_arr = (int *)calloc((size_t)N, sizeof(int));

    for (int i = 0; i < M; ++i) {
        int a, b;
        scanf("%d %d", &a, &b);
        --a; --b;
        edges[2 * i].u = a;
        edges[2 * i].v = b;
        edges[2 * i + 1].u = b;
        edges[2 * i + 1].v = a;
        degree_arr[a]++;
        degree_arr[b]++;
