        for (int i = 0; i < 2 * s; ++i)
            max_tree[base + i] = NEG_INF;

        for (int i = 0; i < s; ++i) {
            int count = i < d ? d - i - 1 : INF;
            min_tree[base + s + i] = count;
        }
        for (int i = s - 1; i >= 1; --i) {
            int a = min_tree[base + i * 2];
            int b = min_tree[base + i * 2 + 1];
            min_tree[base + i] = a < b ? a : b;
        }
    }

    dp = (int *)calloc((size_t)(E ? E : 1), sizeof(int));
    queue_arr = (int *)malloc((size_t)(E ? E : 1) * sizeof(int));
    qtail = 0;

    for (int v = 0; v < N; ++v) {
        int d = degree_arr[v];
        if (d == 0) continue;

        int state = edges[start[v] + d - 1].rev;
        dp[state] = 2;
        queue_arr[qtail++] = state;

        int base = offset[v];
        int leaf = tree_size[v] + d - 1;
        min_tree[base + leaf] = INF;
        for (int node = leaf >> 1; node; node >>= 1) {
            int a = min_tree[base + node * 2];
            int b = min_tree[base + node * 2 + 1];
            min_tree[base + node] = a < b ? a : b;
        }
    }

