        int state = queue_arr[head];
        int a = edges[state].u;
        int pos = state - start[a];

        max_update(a, pos, dp[state]);

        if (pos > 0) {
            range_add(a, 1, 0, tree_size[a], 0, pos, -1);
            if (min_tree[offset[a] + 1] == 0)
                extract_zeros(a, 1, 0, tree_size[a]);
        }
    }

    for (int v = 0; v < N; ++v) {
        int answer = 1;
        for (int i = start[v]; i < start[v + 1]; ++i)
            if (dp[i] > answer) answer = dp[i];

        if (v) putchar(' ');
        printf("%d", answer);
    }
    putchar('\n');

    free(edges);
    free(degree_arr);
    free(start);
    free(tree_size);
    free(offset);
    free(min_tree);
    free(lazy_tree);
    free(max_tree);
    free(dp);
    free(queue_arr);
    return 0;
}
